    <style>
        .btn_contact {width:50px;height:50px;border-radius:50%;display:flex;justify-content:center;align-items:center;}
        /* Servicios: más compactos y CTAs alineados */
        section.services .item-bord{display:flex;flex-direction:column;padding-top:40px;padding-bottom:40px}
        section.services .item-bord .icon-img-70{margin-bottom:20px!important}
        section.services .item-bord a.arrow{margin-top:auto!important;padding-top:24px}
        section.services .item-bord p{margin-bottom:0}
        /* Nosotros: sin scroll horizontal; los paneles se apilan verticalmente */
        .thecontainer{width:100%!important;height:auto!important;display:block!important;transform:none!important}
        .thecontainer .panel{width:100%!important;height:auto!important;padding:60px 0 100px!important;transform:none!important}
        /* WhatsApp flotante */
        .wa-float{position:fixed;right:22px;bottom:22px;z-index:9998;width:58px;height:58px;border-radius:50%;background:#25d366;display:flex;align-items:center;justify-content:center;box-shadow:0 6px 18px rgba(0,0,0,.35);transition:transform .2s}
        .wa-float:hover{transform:scale(1.08)}
        .wa-float svg{width:32px;height:32px;fill:#fff}
        .progress-wrap{bottom:94px!important}
        /* Carrusel de marcas (hacia la derecha) */
        .brands-marquee{overflow:hidden;position:relative;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
        .brands-track{display:flex;width:max-content;animation:brandsRight 60s linear infinite}
        .brands-marquee:hover .brands-track{animation-play-state:paused}
        .brands-track .b-item{flex:0 0 auto;width:190px;height:110px;margin:0 18px;display:flex;align-items:center;justify-content:center}
        .brands-track .b-item img{max-width:100%;max-height:100%;object-fit:contain}
        @keyframes brandsRight{from{transform:translateX(-50%)}to{transform:translateX(0)}}
        @media(prefers-reduced-motion:reduce){.brands-track{animation:none}}
        /* Casos de éxito */
        .case-card{background:#1d1d1d;border:1px solid rgba(255,255,255,.1);border-radius:14px;overflow:hidden;height:100%;display:flex;flex-direction:column}
        .case-card .case-img{height:210px;background:linear-gradient(135deg,#e30a20,#3a0006);display:flex;align-items:center;justify-content:center;background-size:cover;background-position:center}
        .case-card .case-img span{font-size:28px;font-weight:700;color:#fff;text-shadow:0 2px 12px rgba(0,0,0,.6);letter-spacing:1px}
        .case-card .case-body{padding:26px;display:flex;flex-direction:column;flex:1}
        .case-card h6{margin-bottom:10px}
        .case-card p{font-size:14px;opacity:.8}
        .case-card .tag{margin-top:auto;padding-top:16px;font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#e30a20}
        .case-slider{position:relative;overflow:hidden;background:#1d1d1d!important}
        .case-slider img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .8s}
        .case-slider img.on{opacity:1}
        /* Equipo */
        .team-r .t-card{background:#1d1d1d;border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:30px;height:100%;display:flex;gap:24px;align-items:flex-start}
        .team-r .t-photo{flex:0 0 120px;width:120px;height:120px;border-radius:50%;background:linear-gradient(135deg,#e30a20,#3a0006);display:flex;align-items:center;justify-content:center;font-size:36px;font-weight:700;color:#fff;overflow:hidden}
        .team-r .t-photo img{width:100%;height:100%;object-fit:cover}
        @media(max-width:575px){.team-r .t-card{flex-direction:column}}
        /* Testimoniales */
        .testi-box{background:#fff;color:#222;border-radius:16px;padding:32px;height:100%;display:flex;flex-direction:column;box-shadow:0 8px 30px rgba(0,0,0,.15)}
        .testi-box .q{font-size:54px;line-height:1;color:#f4a0a8;font-family:Georgia,serif}
        .testi-box p{font-style:italic;color:#555;font-size:15px;margin:10px 0 24px}
        .testi-box .who{margin-top:auto;display:flex;align-items:center;gap:14px}
        .testi-box .av{flex:0 0 46px;height:46px;border-radius:50%;background:#e30a20;color:#fff;font-weight:700;display:flex;align-items:center;justify-content:center;font-size:14px}
        .testi-box .who strong{display:block;font-size:14px;color:#111}
        .testi-box .who small{color:#777;font-size:12px;line-height:1.3;display:block}
        /* Newsletter popup */
        .nl-overlay{position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:99999;display:none;align-items:center;justify-content:center;padding:16px}
        .nl-overlay.open{display:flex}
        .nl-modal{position:relative;background:#fff;color:#111;border-radius:14px;max-width:880px;width:100%;max-height:94vh;overflow:auto;display:flex}
        .nl-side{flex:0 0 40%;background:linear-gradient(160deg,#e30a20,#2a0004);background-size:cover;background-position:center;min-height:320px}
        .nl-body{flex:1;padding:36px 34px}
        .nl-body h3{font-size:30px;font-weight:800;letter-spacing:1px;margin-bottom:10px;color:#111}
        .nl-body p.lead{font-size:14px;color:#444;margin-bottom:18px}
        .nl-body input[type=text],.nl-body input[type=email]{width:100%;border:1px solid #ccc;border-radius:6px;padding:12px 14px;margin-bottom:12px;color:#111;background:#fff}
        .nl-body button.nl-btn{width:100%;background:#e30a20;color:#fff;border:0;border-radius:6px;padding:14px;font-weight:700;letter-spacing:1px;text-transform:uppercase;cursor:pointer}
        .nl-close{position:absolute;top:10px;right:12px;width:34px;height:34px;border-radius:50%;border:0;background:#111;color:#fff;font-size:18px;cursor:pointer;z-index:2}
        .nl-msg{font-size:13px;margin-top:10px}
        @media(max-width:640px){.nl-side{display:none}}
        /* Formulario leads */
        #lead-form fieldset{border:0;padding:0;margin:0 0 26px}
        #lead-form legend{font-size:15px;font-weight:600;margin-bottom:12px}
        #lead-form .opt{display:block;margin-bottom:8px;font-size:14px;cursor:pointer}
        #lead-form .opt input{margin-right:8px}
        #lead-form input[type=text],#lead-form input[type=email],#lead-form input[type=tel]{width:100%}
    </style>

