    <script>
    (function(){
        function post(form, msgEl, okText, done){
            var btn=form.querySelector('button[type=submit]'); if(btn) btn.disabled=true;
            fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json'}})
              .then(function(r){return r.json().catch(function(){return {ok:r.ok}})})
              .then(function(d){
                  if(d.ok){ msgEl.style.color='#1a7f37'; msgEl.textContent=okText; form.reset(); if(window.grecaptcha&&form.querySelector('.g-recaptcha')) grecaptcha.reset(); if(done) done(); }
                  else { msgEl.style.color='#c00'; msgEl.textContent=d.error||'No se pudo enviar. Intenta de nuevo.'; }
              })
              .catch(function(){ msgEl.style.color='#c00'; msgEl.textContent='Error de conexión. Intenta de nuevo.'; })
              .finally(function(){ if(btn) btn.disabled=false; });
        }
        // Formulario de leads
        var lf=document.getElementById('lead-form');
        if(lf){ lf.addEventListener('submit',function(e){ e.preventDefault(); post(lf, lf.querySelector('.messages'), '¡Gracias! Recibimos tu información y te contactaremos pronto.'); }); }
        // Newsletter
        var ov=document.getElementById('nl-overlay'), nf=document.getElementById('nl-form'), nm=document.getElementById('nl-msg');
        function close(){ ov.classList.remove('open'); try{localStorage.setItem('nl_seen',String(Date.now()));}catch(e){} }
        document.getElementById('nl-close').addEventListener('click',close);
        ov.addEventListener('click',function(e){ if(e.target===ov) close(); });
        document.addEventListener('keydown',function(e){ if(e.key==='Escape') close(); });
        nf.addEventListener('submit',function(e){ e.preventDefault(); post(nf,nm,'¡Listo! Te suscribiste al newsletter.',function(){ setTimeout(close,1800); }); });
        var seen=0; try{seen=parseInt(localStorage.getItem('nl_seen')||'0',10);}catch(e){}
        // Se abre cuando la persona ya recorrió la mitad de la página o tras 30 s, no a los 1.5 s:
        // un popup inmediato en móvil cuenta como "intersticial intrusivo" para Google.
        if(!seen || Date.now()-seen > 7*24*3600*1000){
            var opened=false, openNl=function(){ if(opened) return; opened=true; ov.classList.add('open'); window.removeEventListener('scroll',onSc); };
            var onSc=function(){ var h=document.documentElement; if((h.scrollTop+innerHeight)/h.scrollHeight>0.5) openNl(); };
            window.addEventListener('scroll',onSc,{passive:true}); setTimeout(openNl,30000);
        }
    })();
    </script>

    <script>
    // Desactiva el scroll horizontal (pin) del bloque "Nosotros" creado por hscroll.js
    window.addEventListener('load', function(){
        setTimeout(function(){
            try {
                if (window.ScrollTrigger) {
                    ScrollTrigger.getAll().forEach(function(t){
                        var el = t.trigger || (t.vars && t.vars.trigger);
                        if (el && el.closest && el.closest('.thecontainer')) t.kill(true);
                        else if (el && el.classList && el.classList.contains('thecontainer')) t.kill(true);
                    });
                    ScrollTrigger.refresh();
                }
                if (window.gsap) gsap.set('.thecontainer, .thecontainer .panel', {clearProps:'transform,x,y'});
            } catch(e) {}
        }, 300);
    });
    </script>
    <script>
    document.querySelectorAll('.case-slider').forEach(function(sl){
        var im=sl.querySelectorAll('img'),i=0; if(im.length<2) return;
        setInterval(function(){ im[i].classList.remove('on'); i=(i+1)%im.length; im[i].classList.add('on'); },3500);
    });
    </script>
